def variants(R):
    import itertools
    Ms=[]
    A=[r[:] for r in R]
    def rot(M): return [list(r) for r in zip(*M[::-1])]
    def fl(M): return [r[::-1] for r in M]
    def fv(M): return M[::-1]
    Ms.append(('id',A)); Ms.append(('fh',fl(A))); Ms.append(('fv',fv(A))); Ms.append(('r180',fl(fv(A))))
    r1=rot(A); Ms.append(('r90',r1)); Ms.append(('r270',rot(rot(r1))))
    Ms.append(('tr',rot(fl(A)))); Ms.append(('tl',fl(rot(A))))
    return Ms
